use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res@.len() == if numbers@.len() == 0 { 0 } else { 2 * numbers@.len() - 1 },
        forall|k: int|
            0 <= k < res@.len() ==> (
                if k % 2 == 0 {
                    res@[k] == numbers@[k / 2]
                } else {
                    res@[k] == delim
                }
            ),
        numbers@.len() > 0 ==> res@[res@.len() - 1] == numbers@[numbers@.len() - 1],
{
    let n = numbers.len();
    let mut res: Vec<i32> = Vec::new();

    if n == 0 {
        return res;
    }

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            numbers@.len() == n as int,
            // constructed length so far
            res@.len() == 2 * i as int - if i == 0 { 0 } else { 1 },
            // correctness of elements so far
            forall|k: int|
                0 <= k < res@.len() ==> (
                    if k % 2 == 0 { res@[k] == numbers@[k / 2] }
                    else { res@[k] == delim }
                ),
    {
        if i == 0 {
            res.push(numbers[0]);
        } else {
            res.push(delim);
            res.push(numbers[i]);
        }
        i += 1;
    }

    res
}

} // verus!